public with sharing class ExchangeRateClient {
    private static final String ENDPOINT_BASE = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Pattern CURRENCY_CODE_PATTERN = Pattern.compile('^[A-Z]{3}$');

    public class ExchangeRateException extends Exception {}

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        String normalizedBase = normalizeAndValidateCurrencyCode(baseCurrency);

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies set must not be null or empty.');
        }

        Set<String> normalizedQuotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            normalizedQuotes.add(normalizeAndValidateCurrencyCode(quote));
        }

        Http http = new Http();
        HttpRequest request = buildRequest(normalizedBase, normalizedQuotes);
        HttpResponse response = http.send(request);

        if (response.getStatusCode() == 503) {
            HttpRequest retryRequest = buildRequest(normalizedBase, normalizedQuotes);
            response = http.send(retryRequest);
        }

        Integer statusCode = response.getStatusCode();
        if (statusCode != 200) {
            throw new ExchangeRateException('Exchange rate request failed with status code ' + statusCode + '.');
        }

        return parseRatesResponse(response.getBody(), normalizedQuotes);
    }

    private static String normalizeAndValidateCurrencyCode(String code) {
        if (code == null) {
            throw new ExchangeRateException('Currency code must not be null.');
        }
        String normalized = code.trim().toUpperCase('en_US');
        if (normalized.length() != 3 || !CURRENCY_CODE_PATTERN.matcher(normalized).matches()) {
            throw new ExchangeRateException('Invalid currency code: ' + code);
        }
        return normalized;
    }

    private static HttpRequest buildRequest(String baseCurrency, Set<String> quoteCurrencies) {
        String symbols = String.join(new List<String>(quoteCurrencies), ',');
        String endpoint = ENDPOINT_BASE + '?base=' + baseCurrency + '&symbols=' + symbols;

        HttpRequest request = new HttpRequest();
        request.setEndpoint(endpoint);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        return request;
    }

    private static Map<String, Decimal> parseRatesResponse(String body, Set<String> quoteCurrencies) {
        if (String.isBlank(body)) {
            throw new ExchangeRateException('Exchange rate response body is empty.');
        }

        Map<String, Object> payload;
        try {
            Object deserialized = JSON.deserializeUntyped(body);
            if (!(deserialized instanceof Map<String, Object>)) {
                throw new ExchangeRateException('Exchange rate response body is not a JSON object.');
            }
            payload = (Map<String, Object>) deserialized;
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException('Failed to parse exchange rate response body.', e);
        }

        Object ratesObj = payload.get('rates');
        if (!(ratesObj instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Exchange rate response is missing a valid rates object.');
        }
        Map<String, Object> rawRates = (Map<String, Object>) ratesObj;

        Map<String, Decimal> rates = new Map<String, Decimal>();
        for (String quoteCode : quoteCurrencies) {
            if (!rawRates.containsKey(quoteCode)) {
                throw new ExchangeRateException('Missing rate for requested currency: ' + quoteCode);
            }
            rates.put(quoteCode, toDecimalRate(rawRates.get(quoteCode), quoteCode));
        }

        return rates;
    }

    private static Decimal toDecimalRate(Object rawValue, String quoteCode) {
        if (rawValue == null) {
            throw new ExchangeRateException('Rate is null for requested currency: ' + quoteCode);
        }
        if (rawValue instanceof Decimal) {
            return (Decimal) rawValue;
        }
        if (rawValue instanceof Double) {
            return Decimal.valueOf((Double) rawValue);
        }
        if (rawValue instanceof Integer) {
            return Decimal.valueOf((Integer) rawValue);
        }
        if (rawValue instanceof Long) {
            return Decimal.valueOf((Long) rawValue);
        }
        throw new ExchangeRateException('Invalid rate value for requested currency: ' + quoteCode);
    }
}
