public with sharing class RecordSearchService {
    public class SearchException extends Exception {
    }

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }

            if (String.isBlank(objectApiName)) {
                throw new SearchException('Object API name must not be blank.');
            }

            if (fields == null || fields.isEmpty()) {
                throw new SearchException('Fields list must not be null or empty.');
            }

            Schema.SObjectType sObjType = Schema.getGlobalDescribe().get(objectApiName.trim());
            if (sObjType == null) {
                throw new SearchException('Object does not exist: ' + objectApiName);
            }

            Schema.DescribeSObjectResult objDescribe = sObjType.getDescribe();
            if (!objDescribe.isAccessible() || !objDescribe.isQueryable()) {
                throw new SearchException('Object is not accessible: ' + objDescribe.getName());
            }

            Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

            Set<String> selectFieldSet = new Set<String>();
            List<String> selectFields = new List<String>();

            Schema.SObjectField idField = fieldMap.get('Id');
            if (idField == null || !idField.getDescribe().isAccessible()) {
                throw new SearchException('Id field is not accessible.');
            }
            String canonicalIdName = idField.getDescribe().getName();
            selectFieldSet.add(canonicalIdName);
            selectFields.add(canonicalIdName);

            for (String fieldName : fields) {
                if (String.isBlank(fieldName)) {
                    throw new SearchException('Field name must not be blank.');
                }
                Schema.SObjectField sField = fieldMap.get(fieldName.trim());
                if (sField == null) {
                    throw new SearchException('Field does not exist: ' + fieldName);
                }
                Schema.DescribeFieldResult dfr = sField.getDescribe();
                if (!dfr.isAccessible()) {
                    throw new SearchException('Field is not accessible: ' + dfr.getName());
                }
                String canonicalName = dfr.getName();
                if (selectFieldSet.add(canonicalName)) {
                    selectFields.add(canonicalName);
                }
            }

            List<String> whereConditions = new List<String>();
            Map<String, Object> bindVars = new Map<String, Object>();
            Integer bindIndex = 0;

            if (filters != null && !filters.isEmpty()) {
                for (String filterKey : filters.keySet()) {
                    if (String.isBlank(filterKey)) {
                        throw new SearchException('Filter field name must not be blank.');
                    }
                    Schema.SObjectField sField = fieldMap.get(filterKey.trim());
                    if (sField == null) {
                        throw new SearchException('Filter field does not exist: ' + filterKey);
                    }
                    Schema.DescribeFieldResult dfr = sField.getDescribe();
                    if (!dfr.isAccessible()) {
                        throw new SearchException('Filter field is not accessible: ' + dfr.getName());
                    }
                    if (!dfr.isFilterable()) {
                        throw new SearchException('Field cannot be filtered: ' + dfr.getName());
                    }

                    Object rawVal = filters.get(filterKey);
                    if (rawVal == null) {
                        whereConditions.add(dfr.getName() + ' = null');
                    } else {
                        Object bindVal = normalizeBindValue(rawVal, dfr);
                        String bindKey = 'filterBind' + bindIndex++;
                        bindVars.put(bindKey, bindVal);
                        whereConditions.add(dfr.getName() + ' = :' + bindKey);
                    }
                }
            }

            String orderByClause = '';
            if (!String.isBlank(orderByField)) {
                Schema.SObjectField sField = fieldMap.get(orderByField.trim());
                if (sField == null) {
                    throw new SearchException('Order-by field does not exist: ' + orderByField);
                }
                Schema.DescribeFieldResult dfr = sField.getDescribe();
                if (!dfr.isAccessible()) {
                    throw new SearchException('Order-by field is not accessible: ' + dfr.getName());
                }
                if (!dfr.isSortable()) {
                    throw new SearchException('Field cannot be sorted: ' + dfr.getName());
                }
                orderByClause = ' ORDER BY ' + dfr.getName() + ' ASC';
            }

            String soql = 'SELECT ' + String.join(selectFields, ', ') + ' FROM ' + objDescribe.getName();
            if (!whereConditions.isEmpty()) {
                soql += ' WHERE ' + String.join(whereConditions, ' AND ');
            }
            soql += orderByClause;
            soql += ' LIMIT ' + maxRows;

            if (bindVars.isEmpty()) {
                return Database.query(soql, AccessLevel.USER_MODE);
            }
            return Database.queryWithBinds(soql, bindVars, AccessLevel.USER_MODE);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            throw new SearchException(e.getMessage(), e);
        }
    }

    private static Object normalizeBindValue(Object rawVal, Schema.DescribeFieldResult dfr) {
        if (rawVal instanceof Iterable<Object> || rawVal instanceof SObject) {
            throw new SearchException('Invalid filter value type for field: ' + dfr.getName());
        }
        if (dfr.getSoapType() == Schema.SoapType.INTEGER && rawVal instanceof Decimal) {
            Decimal decVal = (Decimal) rawVal;
            if (decVal.scale() > 0 && decVal.stripTrailingZeros().scale() > 0) {
                throw new SearchException('Invalid integer value for field: ' + dfr.getName());
            }
            return decVal.intValue();
        }
        return rawVal;
    }
}
