public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(label='Email' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email' description='Finds an existing contact by email address.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        Set<String> normalizedEmails = new Set<String>();
        for (Request req : requests) {
            if (req != null && !String.isBlank(req.email)) {
                normalizedEmails.add(req.email.trim().toLowerCase());
            }
        }

        Map<String, Id> emailToContactId = new Map<String, Id>();
        if (!normalizedEmails.isEmpty()) {
            for (Contact con : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :normalizedEmails
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                if (con.Email != null) {
                    String key = con.Email.trim().toLowerCase();
                    if (!emailToContactId.containsKey(key)) {
                        emailToContactId.put(key, con.Id);
                    }
                }
            }
        }

        for (Request req : requests) {
            Result res = new Result();
            if (req != null && !String.isBlank(req.email)) {
                String key = req.email.trim().toLowerCase();
                Id matchedId = emailToContactId.get(key);
                res.contactId = matchedId;
                res.found = (matchedId != null);
            } else {
                res.contactId = null;
                res.found = false;
            }
            results.add(res);
        }

        return results;
    }
}
