public with sharing class OrderPayloadParser {

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;

        public Order() {
            this.lines = new List<Line>();
            this.total = 0;
        }
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    public static OrderPayloadParser.Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Order payload cannot be null or blank.');
        }

        try {
            Object untyped = JSON.deserializeUntyped(body);
            if (!(untyped instanceof Map<String, Object>)) {
                throw new PayloadException('Order payload must be a JSON object.');
            }

            Map<String, Object> root = (Map<String, Object>) untyped;
            Order result = new Order();

            Object numberObj = root.get('number');
            if (!(numberObj instanceof String) || String.isBlank((String) numberObj)) {
                throw new PayloadException('Order number is required and cannot be blank.');
            }
            result.orderNumber = (String) numberObj;

            Object dateObj = root.get('date');
            if (dateObj != null) {
                if (!(dateObj instanceof String)) {
                    throw new PayloadException('Order date must be a string in ISO yyyy-MM-dd format.');
                }
                result.orderDate = Date.valueOf((String) dateObj);
            }

            Object currencyObj = root.get('currency');
            if (currencyObj != null) {
                if (!(currencyObj instanceof String)) {
                    throw new PayloadException('Currency must be a string.');
                }
                result.currencyCode = (String) currencyObj;
            }

            Object customerObj = root.get('customer');
            if (customerObj != null) {
                if (!(customerObj instanceof Map<String, Object>)) {
                    throw new PayloadException('Customer must be a JSON object.');
                }
                Map<String, Object> customerMap = (Map<String, Object>) customerObj;
                Object emailObj = customerMap.get('email');
                if (emailObj != null) {
                    if (!(emailObj instanceof String)) {
                        throw new PayloadException('Customer email must be a string.');
                    }
                    result.customerEmail = (String) emailObj;
                }
            }

            result.lines = new List<Line>();
            result.total = 0;

            Object linesObj = root.get('lines');
            if (linesObj != null) {
                if (!(linesObj instanceof List<Object>)) {
                    throw new PayloadException('Order lines must be a JSON array.');
                }
                List<Object> rawLines = (List<Object>) linesObj;
                for (Object rawLine : rawLines) {
                    if (!(rawLine instanceof Map<String, Object>)) {
                        throw new PayloadException('Each order line must be a JSON object.');
                    }
                    Map<String, Object> lineMap = (Map<String, Object>) rawLine;
                    Line line = new Line();

                    Object skuObj = lineMap.get('sku');
                    if (!(skuObj instanceof String) || String.isBlank((String) skuObj)) {
                        throw new PayloadException('Line sku is required and cannot be blank.');
                    }
                    line.sku = (String) skuObj;

                    Integer qty = toInteger(lineMap.get('quantity'));
                    if (qty == null || qty <= 0) {
                        throw new PayloadException('Line quantity is required and must be positive.');
                    }
                    line.quantity = qty;

                    Decimal price = toDecimal(lineMap.get('unitPrice'));
                    if (price == null || price < 0) {
                        throw new PayloadException('Line unitPrice is required and cannot be negative.');
                    }
                    line.unitPrice = price;

                    Object discountObj = lineMap.get('discount');
                    if (discountObj == null) {
                        line.discount = 0;
                    } else {
                        Decimal disc = toDecimal(discountObj);
                        if (disc < 0 || disc > 1) {
                            throw new PayloadException('Line discount must be between 0 and 1.');
                        }
                        line.discount = disc;
                    }

                    Decimal rawLineTotal = Decimal.valueOf(line.quantity) * line.unitPrice * (1 - line.discount);
                    line.lineTotal = rawLineTotal.setScale(2, System.RoundingMode.HALF_UP);

                    result.lines.add(line);
                    result.total += line.lineTotal;
                }
            }

            return result;
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Invalid order payload: ' + e.getMessage(), e);
        }
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        if (order == null) {
            throw new PayloadException('Order cannot be null.');
        }

        Integer lineCount = (order.lines != null) ? order.lines.size() : 0;
        Decimal total = (order.total != null) ? order.total : 0;

        JSONGenerator gen = JSON.createGenerator(false);
        gen.writeStartObject();
        if (order.orderNumber != null) {
            gen.writeStringField('number', order.orderNumber);
        } else {
            gen.writeNullField('number');
        }
        gen.writeStringField('status', 'RECEIVED');
        gen.writeNumberField('lineCount', lineCount);
        gen.writeNumberField('total', total);
        gen.writeEndObject();
        return gen.getAsString();
    }

    private static Integer toInteger(Object val) {
        if (val == null) {
            return null;
        }
        if (val instanceof Integer) {
            return (Integer) val;
        }
        if (val instanceof Long) {
            return ((Long) val).intValue();
        }
        if (val instanceof Decimal) {
            Decimal d = (Decimal) val;
            if (d == d.intValue()) {
                return d.intValue();
            }
        }
        throw new PayloadException('Expected an integer value.');
    }

    private static Decimal toDecimal(Object val) {
        if (val == null) {
            return null;
        }
        if (val instanceof Decimal) {
            return (Decimal) val;
        }
        if (val instanceof Integer) {
            return Decimal.valueOf((Integer) val);
        }
        if (val instanceof Long) {
            return Decimal.valueOf((Long) val);
        }
        if (val instanceof Double) {
            return Decimal.valueOf((Double) val);
        }
        throw new PayloadException('Expected a numeric value.');
    }
}
