        Assert.areEqual(7.50, ShippingCostCalculator.quote(1, 'DOMESTIC', true, 100.00));
        Assert.areEqual(14.25, ShippingCostCalculator.quote(5, 'domestic', true, 250.00));

        // EU and WORLD standard with orderValue >= 100 do NOT ship free
        Assert.areEqual(7.00, ShippingCostCalculator.quote(1, 'EU', false, 100.00));
        Assert.areEqual(7.00, ShippingCostCalculator.quote(1, 'EU', null, 200.00));
        Assert.areEqual(11.00, ShippingCostCalculator.quote(1, 'WORLD', false, 100.00));
        Assert.areEqual(11.00, ShippingCostCalculator.quote(1, 'WORLD', null, 200.00));
    }

    @IsTest
    static void testHalfUpRoundingToTwoDecimalPlaces() {
        // 21 kg DOMESTIC express: 18.75 * 1.0 * 1.5 = 28.125 -> 28.13 (even hundredth digit before 5)
        Decimal quote21DomExp = ShippingCostCalculator.quote(21, 'DOMESTIC', true, 50.00);
        Assert.areEqual(28.13, quote21DomExp);
        Assert.areEqual(2, quote21DomExp.scale());

        // 23 kg DOMESTIC express: 20.25 * 1.0 * 1.5 = 30.375 -> 30.38 (odd hundredth digit before 5)
        Assert.areEqual(30.38, ShippingCostCalculator.quote(23, 'DOMESTIC', true, 50.00));

        // 25 kg DOMESTIC express: 21.75 * 1.0 * 1.5 = 32.625 -> 32.63 (even hundredth digit before 5)
        Assert.areEqual(32.63, ShippingCostCalculator.quote(25, 'DOMESTIC', true, 50.00));

        // 21 kg EU express: 18.75 * 1.4 * 1.5 = 39.375 -> 39.38
        Assert.areEqual(39.38, ShippingCostCalculator.quote(21, 'EU', true, 50.00));

        // 23 kg EU express: 20.25 * 1.4 * 1.5 = 42.525 -> 42.53
        Assert.areEqual(42.53, ShippingCostCalculator.quote(23, 'EU', true, 50.00));

        // 21 kg WORLD express: 18.75 * 2.2 * 1.5 = 61.875 -> 61.88
        Assert.areEqual(61.88, ShippingCostCalculator.quote(21, 'WORLD', true, 50.00));

        // 23 kg WORLD express: 20.25 * 2.2 * 1.5 = 66.825 -> 66.83
        Assert.areEqual(66.83, ShippingCostCalculator.quote(23, 'WORLD', true, 50.00));

        // Scale check on exact result
        Decimal exactQuote = ShippingCostCalculator.quote(1, 'DOMESTIC', false, 50.00);
        Assert.areEqual(5.00, exactQuote);
        Assert.areEqual(2, exactQuote.scale());
    }
