public with sharing class PicklistService {
    private static Map<String, Schema.SObjectType> globalDescribe {
        get {
            if (globalDescribe == null) {
                globalDescribe = Schema.getGlobalDescribe();
            }
            return globalDescribe;
        }
        set;
    }

    public class PicklistServiceException extends Exception {
    }

    public class Option {
        @AuraEnabled
        public String value { get; set; }
        @AuraEnabled
        public String label { get; set; }
        @AuraEnabled
        public Boolean isDefault { get; set; }

        public Option() {
        }

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }

        public Option(Schema.PicklistEntry entry) {
            this.value = entry.getValue();
            this.label = entry.getLabel();
            this.isDefault = entry.isDefaultValue();
        }

        public Boolean equals(Object obj) {
            if (this === obj) {
                return true;
            }
            if (obj == null || !(obj instanceof Option)) {
                return false;
            }
            Option other = (Option) obj;
            return this.value == other.value &&
                this.label == other.label &&
                this.isDefault == other.isDefault;
        }

        public Integer hashCode() {
            Integer result = 17;
            result = 31 * result + (this.value != null ? System.hashCode(this.value) : 0);
            result = 31 * result + (this.label != null ? System.hashCode(this.label) : 0);
            result = 31 * result + (this.isDefault != null ? System.hashCode(this.isDefault) : 0);
            return result;
        }
    }

    @AuraEnabled(cacheable=true)
    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be null or blank.');
        }

        try {
            Schema.SObjectType sObjType = globalDescribe.get(objectApiName);
            if (sObjType == null) {
                throw new PicklistServiceException('Object does not exist: ' + objectApiName);
            }

            Schema.DescribeSObjectResult sObjDescribe = sObjType.getDescribe(SObjectDescribeOptions.DEFERRED);
            Map<String, Schema.SObjectField> fieldMap = sObjDescribe.fields.getMap();
            Schema.SObjectField sObjField = fieldMap.get(fieldApiName);
            if (sObjField == null) {
                throw new PicklistServiceException(
                    'Field ' + fieldApiName + ' does not exist on object ' + objectApiName + '.'
                );
            }

            Schema.DescribeFieldResult fieldDescribe = sObjField.getDescribe();
            Schema.DisplayType fieldType = fieldDescribe.getType();
            if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
                throw new PicklistServiceException(
                    'Field ' + fieldApiName + ' on object ' + objectApiName + ' is not a picklist field.'
                );
            }

            List<Option> options = new List<Option>();
            for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
                if (entry.isActive()) {
                    options.add(new Option(entry));
                }
            }
            return options;
        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new PicklistServiceException(e.getMessage(), e);
        }
    }
}
