public with sharing class ShipmentEventHandler {

    private static final String STATUS_SHIPPED = 'Shipped';
    private static final String STATUS_CANCELLED = 'Cancelled';

    public static void handle(List<FB_Shipment_Event__e> events) {
        if (events == null || events.isEmpty()) {
            return;
        }

        Map<String, FB_Shipment_Event__e> latestEventByOrderNumber = new Map<String, FB_Shipment_Event__e>();
        for (FB_Shipment_Event__e eventRecord : events) {
            if (eventRecord == null || String.isBlank(eventRecord.Order_Number__c)) {
                continue;
            }
            String normalizedOrderNumber = eventRecord.Order_Number__c.trim().toUpperCase();
            latestEventByOrderNumber.put(normalizedOrderNumber, eventRecord);
        }

        if (latestEventByOrderNumber.isEmpty()) {
            return;
        }

        List<FB_Sales_Order__c> matchingOrders = [
            SELECT Id, Order_Number__c, Status__c
            FROM FB_Sales_Order__c
            WHERE Order_Number__c IN :latestEventByOrderNumber.keySet()
        ];

        Date shippedDate = Date.today();
        List<FB_Sales_Order__c> ordersToUpdate = new List<FB_Sales_Order__c>();

        for (FB_Sales_Order__c orderRecord : matchingOrders) {
            if (orderRecord.Status__c == STATUS_CANCELLED || String.isBlank(orderRecord.Order_Number__c)) {
                continue;
            }

            String normalizedOrderNumber = orderRecord.Order_Number__c.trim().toUpperCase();
            FB_Shipment_Event__e winningEvent = latestEventByOrderNumber.get(normalizedOrderNumber);
            if (winningEvent == null) {
                continue;
            }

            orderRecord.Status__c = STATUS_SHIPPED;
            orderRecord.Tracking_Number__c = winningEvent.Tracking_Number__c;
            orderRecord.Carrier__c = winningEvent.Carrier__c;
            orderRecord.Shipped_Date__c = shippedDate;
            ordersToUpdate.add(orderRecord);
        }

        if (!ordersToUpdate.isEmpty()) {
            update ordersToUpdate;
        }
    }
}
