public with sharing class OpportunityPipelineHandler {
    private static Boolean isUpdatingAccounts = false;

    public static void handle() {
        if (isUpdatingAccounts || !Trigger.isAfter) {
            return;
        }

        switch on Trigger.operationType {
            when AFTER_INSERT {
                afterInsert((List<Opportunity>) Trigger.new);
            }
            when AFTER_UPDATE {
                afterUpdate((List<Opportunity>) Trigger.new, (Map<Id, Opportunity>) Trigger.oldMap);
            }
            when AFTER_DELETE {
                afterDelete((List<Opportunity>) Trigger.old);
            }
            when AFTER_UNDELETE {
                afterUndelete((List<Opportunity>) Trigger.new);
            }
        }
    }

    public static void afterInsert(List<Opportunity> newOpps) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newOpps) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        updateAccounts(accountIds);
    }

    public static void afterUpdate(List<Opportunity> newOpps, Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newOpps) {
            Opportunity oldOpp = oldMap.get(opp.Id);
            if (opp.AccountId != oldOpp.AccountId) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
                if (oldOpp.AccountId != null) {
                    accountIds.add(oldOpp.AccountId);
                }
            } else if (opp.AccountId != null) {
                if (opp.IsClosed != oldOpp.IsClosed || opp.Amount != oldOpp.Amount) {
                    accountIds.add(opp.AccountId);
                }
            }
        }
        updateAccounts(accountIds);
    }

    public static void afterDelete(List<Opportunity> oldOpps) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : oldOpps) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        updateAccounts(accountIds);
    }

    public static void afterUndelete(List<Opportunity> newOpps) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newOpps) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        updateAccounts(accountIds);
    }

    public static void updateAccounts(Set<Id> accountIds) {
        accountIds.remove(null);
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Id accountId : accountIds) {
            accountsToUpdate.put(
                accountId,
                new Account(
                    Id = accountId,
                    FB_Open_Pipeline__c = 0,
                    FB_Open_Opportunities__c = 0
                )
            );
        }

        for (AggregateResult ar : [
            SELECT AccountId accId, COUNT(Id) openCount, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('accId');
            Integer openCount = (Integer) ar.get('openCount');
            Decimal totalAmount = (Decimal) ar.get('totalAmount');

            Account acc = accountsToUpdate.get(accId);
            if (acc != null) {
                acc.FB_Open_Opportunities__c = openCount != null ? openCount : 0;
                acc.FB_Open_Pipeline__c = totalAmount != null ? totalAmount : 0;
            }
        }

        isUpdatingAccounts = true;
        try {
            update accountsToUpdate.values();
        } finally {
            isUpdatingAccounts = false;
        }
    }
}
