public with sharing class LogPurgeJob implements Schedulable {
    public static final String JOB_NAME = 'Log purge (nightly)';
    public static final String CRON_EXP = '0 0 2 * * ?';

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        Datetime standardCutoff = Datetime.now().addDays(-30);
        Datetime errorCutoff = Datetime.now().addDays(-180);

        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE
                (CreatedDate < :standardCutoff AND Level__c != 'ERROR')
                OR (CreatedDate < :errorCutoff AND Level__c = 'ERROR')
            LIMIT 10000
        ];

        if (!logsToDelete.isEmpty()) {
            delete logsToDelete;
        }
    }

    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_EXP, new LogPurgeJob());
    }
}
