public with sharing class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> totalsByAccountId = new Map<Id, Decimal>();
        if (accountIds == null || accountIds.isEmpty()) {
            return totalsByAccountId;
        }

        for (Id accountId : accountIds) {
            if (accountId != null) {
                totalsByAccountId.put(accountId, 0);
            }
        }

        if (totalsByAccountId.isEmpty()) {
            return totalsByAccountId;
        }

        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :totalsByAccountId.keySet()
                AND IsWon = true
                AND CloseDate = THIS_YEAR
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal totalAmount = (Decimal) ar.get('totalAmount');
            totalsByAccountId.put(accountId, totalAmount != null ? totalAmount : 0);
        }

        return totalsByAccountId;
    }
}
