        Set<Id> accountIds = new Set<Id>{ accountId1, accountId2 };

        List<Opportunity> mockOpportunities = new List<Opportunity>{
            // 25.34 * 10 / 100 = 2.534 -> rounds to 2.53
            new Opportunity(
                Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
                Name = 'Prospecting Opp 1',
                AccountId = accountId1,
                StageName = 'Prospecting',
                Amount = 25.34,
                Probability = 10
            ),
            // 50.34 * 10 / 100 = 5.034 -> rounds to 5.03
            // Sum of rounded per opportunity is 7.56 (unrounded sum 7.568 would round to 7.57)
            new Opportunity(
                Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
                Name = 'Prospecting Opp 2',
                AccountId = accountId2,
                StageName = 'Prospecting',
                Amount = 50.34,
                Probability = 10
            ),
            // 10.15 * 25 / 100 = 2.5375 -> rounds to 2.54
            new Opportunity(
                Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
                Name = 'Qualification Opp 1',
                AccountId = accountId1,
                StageName = 'Qualification',
                Amount = 10.15,
                Probability = 25
            ),
            // 200.00 * 50 / 100 = 100.00
            new Opportunity(
                Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
                Name = 'Qualification Opp 2',
                AccountId = accountId2,
                StageName = 'Qualification',
                Amount = 200.00,
                Probability = 50
            ),
            // 1000.00 * 75 / 100 = 750.00
            new Opportunity(
                Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
                Name = 'Negotiation Opp 1',
                AccountId = accountId1,
                StageName = 'Negotiation/Review',
                Amount = 1000.00,
