    private static final String CLOSED_WON = 'Closed Won';

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = OpportunitiesSelector.newInstance()
            .selectById(opportunityIds);

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        Integer closedCount = 0;
        Date today = Date.today();

        for (Opportunity opp : opportunities) {
            if (opp.StageName == CLOSED_WON) {
                continue;
            }

            opp.StageName = CLOSED_WON;
            opp.CloseDate = today;
            uow.registerDirty(opp);

            uow.registerPublishAfterSuccessTransaction(
                new Deal_Won__e(
                    Opportunity_Id__c = opp.Id,
                    Amount__c = opp.Amount
                )
            );

            closedCount++;
        }

        if (closedCount > 0) {
            uow.commitWork();
        }

        return closedCount;
    }
