```apex
public with sharing class ErpCustomerSync implements Queueable, Database.AllowsCallouts {
    private static final String ENDPOINT = 'callout:ERP/api/customers';
    private static final Integer MAX_BATCH_SIZE = 200;

    private final List<CustomerPayload> payloads;

    public ErpCustomerSync(List<Account> accounts) {
        this.payloads = buildPayloads(accounts);
    }

    public static Id enqueue(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new ErpCustomerSync(accounts));
    }

    public void execute(QueueableContext context) {
        sendPayloads(this.payloads);
    }

    public static void sendCustomers(List<Account> accounts) {
        sendPayloads(buildPayloads(accounts));
    }

    private static List<CustomerPayload> buildPayloads(List<Account> accounts) {
        List<CustomerPayload> results = new List<CustomerPayload>();
        if (accounts == null) {
            return results;
        }
        for (Account acc : accounts) {
            if (acc != null) {
                results.add(new CustomerPayload(acc));
            }
        }
        return results;
    }

    private static void sendPayloads(List<CustomerPayload> allPayloads) {
        if (allPayloads == null || allPayloads.isEmpty()) {
            return;
        }

        Http http = new Http();
        List<CustomerPayload> currentBatch = new List<CustomerPayload>();

        for (Integer i = 0; i < allPayloads.size(); i++) {
            currentBatch.add(allPayloads[i]);
            if (currentBatch.size() == MAX_BATCH_SIZE || i == allPayloads.size() - 1) {
                HttpRequest req = new HttpRequest();
                req.setEndpoint(ENDPOINT);
                req.setMethod('POST');
                req.setHeader('Content-Type', 'application/json');
                req.setBody(JSON.serialize(currentBatch));
                http.send(req);

                currentBatch.clear();
            }
        }
    }

    public class CustomerPayload {
        public String salesforceId;
        public String name;
        public String country;

        public CustomerPayload(Account acc) {
            this.salesforceId = acc.Id != null ? String.valueOf(acc.Id) : null;
            this.name = acc.Name;
            this.country = String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry;
        }
    }
}
