    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        List<Opportunity> opportunities = [
            SELECT Id, Name, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ];

        if (opportunities.isEmpty()) {
            return failedOpportunityIds;
        }

        Date dueDate = Date.today().addDays(7);
        List<Task> tasksToInsert = new List<Task>();

        for (Opportunity opp : opportunities) {
            tasksToInsert.add(
                new Task(
                    WhatId = opp.Id,
                    OwnerId = opp.OwnerId,
                    Subject = 'Follow up: ' + opp.Name,
                    ActivityDate = dueDate,
                    Status = 'Not Started',
                    Priority = 'Normal'
                )
            );
        }

        List<Database.SaveResult> saveResults = Database.insert(tasksToInsert, false);
        for (Integer i = 0; i < saveResults.size(); i++) {
            if (!saveResults[i].isSuccess()) {
                failedOpportunityIds.add(tasksToInsert[i].WhatId);
            }
        }

        return failedOpportunityIds;
    }
}
