public with sharing class LineItemDiscountHandler {
    /**
     * Populates Discount on new OpportunityLineItem records when Discount is null,
     * using the standard discount rules defined in PricingRules.
     */
    public static void beforeInsert(List<OpportunityLineItem> newLines) {
        if (newLines == null || newLines.isEmpty()) {
            return;
        }

        Set<Id> productIds = new Set<Id>();
        Set<Id> pricebookEntryIds = new Set<Id>();

        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null) {
                if (line.Product2Id != null) {
                    productIds.add(line.Product2Id);
                } else if (line.PricebookEntryId != null) {
                    pricebookEntryIds.add(line.PricebookEntryId);
                }
            }
        }

        if (productIds.isEmpty() && pricebookEntryIds.isEmpty()) {
            return;
        }

        Map<Id, Product2> productsById = new Map<Id, Product2>();
        if (!productIds.isEmpty()) {
            productsById = new Map<Id, Product2>(
                [SELECT Id, Family FROM Product2 WHERE Id IN :productIds]
            );
        }

        Map<Id, PricebookEntry> pbesById = new Map<Id, PricebookEntry>();
        if (!pricebookEntryIds.isEmpty()) {
            pbesById = new Map<Id, PricebookEntry>(
                [SELECT Id, Product2Id, Product2.Family FROM PricebookEntry WHERE Id IN :pricebookEntryIds]
            );
        }

        for (OpportunityLineItem line : newLines) {
            if (line.Discount != null) {
                continue;
            }

            if (line.Product2Id != null && productsById.containsKey(line.Product2Id)) {
                Product2 prod = productsById.get(line.Product2Id);
                line.Discount = PricingRules.standardDiscountForFamily(prod.Family);
            } else if (line.PricebookEntryId != null && pbesById.containsKey(line.PricebookEntryId)) {
                PricebookEntry pbe = pbesById.get(line.PricebookEntryId);
                line.Discount = PricingRules.standardDiscountForFamily(pbe.Product2.Family);
            }
        }
    }

    public static void handleBeforeInsert(List<OpportunityLineItem> newLines) {
        beforeInsert(newLines);
    }

    public static void applyStandardDiscounts(List<OpportunityLineItem> newLines) {
        beforeInsert(newLines);
    }
}
