```apex
public with sharing class CaseSurveyJob implements Queueable {
    private final Set<Id> caseIds;

    public CaseSurveyJob(Id caseId) {
        this(caseId != null ? new Set<Id>{ caseId } : new Set<Id>());
    }

    public CaseSurveyJob(List<Id> caseIds) {
        this(caseIds != null ? new Set<Id>(caseIds) : new Set<Id>());
    }

    public CaseSurveyJob(Set<Id> caseIds) {
        this.caseIds = caseIds != null ? new Set<Id>(caseIds) : new Set<Id>();
        this.caseIds.remove(null);
    }

    public void execute(QueueableContext context) {
        if (this.caseIds.isEmpty()) {
            return;
        }

        List<Task> tasksToInsert = new List<Task>();
        Date dueDate = Date.today().addDays(2);

        for (Case c : [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :this.caseIds
            AND ContactId != null
        ]) {
            tasksToInsert.add(new Task(
                WhatId = c.Id,
                WhoId = c.ContactId,
                Subject = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = dueDate,
                Status = 'Not Started'
            ));
        }

        if (!tasksToInsert.isEmpty()) {
            Database.insert(tasksToInsert, false);
        }
    }
}
