public with sharing class AccountCountrySync {

    public static void handleAfterUpdate(List<Account> newAccounts, Map<Id, Account> oldAccountMap) {
        if (newAccounts == null || newAccounts.isEmpty() || oldAccountMap == null) {
            return;
        }

        Map<Id, Account> changedAccounts = new Map<Id, Account>();
        for (Account acc : newAccounts) {
            Account oldAcc = oldAccountMap.get(acc.Id);
            if (oldAcc != null && acc.BillingCountry != oldAcc.BillingCountry) {
                changedAccounts.put(acc.Id, acc);
            }
        }

        if (changedAccounts.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact con : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccounts.keySet()
        ]) {
            Account newAcc = changedAccounts.get(con.AccountId);
            Account oldAcc = oldAccountMap.get(con.AccountId);

            if (String.isBlank(con.MailingCountry) || con.MailingCountry == oldAcc.BillingCountry) {
                con.MailingCountry = newAcc.BillingCountry;
                contactsToUpdate.add(con);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
