import { LightningElement, api, wire } from 'lwc';
import { getRecord, getFieldValue } from 'lightning/uiRecordApi';
import NAME_FIELD from '@salesforce/schema/Account.Name';
import INDUSTRY_FIELD from '@salesforce/schema/Account.Industry';
import ANNUAL_REVENUE_FIELD from '@salesforce/schema/Account.AnnualRevenue';
import OWNER_NAME_FIELD from '@salesforce/schema/Account.Owner.Name';

const FIELDS = [
    NAME_FIELD,
    INDUSTRY_FIELD,
    ANNUAL_REVENUE_FIELD,
    OWNER_NAME_FIELD
];

export default class AccountHeader extends LightningElement {
    @api recordId;

    record;
    error;

    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    wiredAccount({ data, error }) {
        if (data) {
            this.record = data;
            this.error = undefined;
        } else if (error) {
            this.error = error;
            this.record = undefined;
        } else {
            this.record = undefined;
            this.error = undefined;
        }
    }

    get isLoading() {
        return !this.record && !this.error;
    }

    get name() {
        return (
            getFieldValue(this.record, NAME_FIELD) ??
            this.record?.fields?.Name?.value
        );
    }

    get industry() {
        return (
            getFieldValue(this.record, INDUSTRY_FIELD) ??
            this.record?.fields?.Industry?.value
        );
    }

    get annualRevenue() {
        return (
            getFieldValue(this.record, ANNUAL_REVENUE_FIELD) ??
            this.record?.fields?.AnnualRevenue?.value
        );
    }

    get ownerName() {
        return (
            getFieldValue(this.record, OWNER_NAME_FIELD) ??
            this.record?.fields?.Owner?.value?.fields?.Name?.value ??
            this.record?.fields?.Owner?.displayValue ??
            this.record?.fields?.['Owner.Name']?.value
        );
    }

    get errorMessage() {
        return this.error?.body?.message;
    }
}
