        this.clearPendingTimer();
        this.latestRequestId += 1;
    }

    handleSearchChange(event) {
        const rawValue = event.detail?.value ?? event.target?.value ?? '';
        const searchTerm = rawValue.trim();

        this.clearPendingTimer();

        if (searchTerm.length < MIN_SEARCH_LENGTH) {
            this.latestRequestId += 1;
            this.contacts = [];
            this.errorMessage = null;
            return;
        }

        // eslint-disable-next-line @lwc/lwc/no-async-operation
        this.debounceTimeout = setTimeout(() => {
            this.debounceTimeout = null;
            this.executeSearch(searchTerm);
        }, DEBOUNCE_DELAY);
    }

    async executeSearch(searchTerm) {
        const requestId = ++this.latestRequestId;
        try {
            const results = await searchContacts({ searchTerm });
            if (requestId !== this.latestRequestId) {
                return;
            }
            this.contacts = results || [];
            this.errorMessage = null;
        } catch (error) {
            if (requestId !== this.latestRequestId) {
                return;
            }
            this.contacts = [];
            this.errorMessage = error?.body?.message ?? error?.message ?? 'An error occurred';
        }
    }

    clearPendingTimer() {
        if (this.debounceTimeout) {
            clearTimeout(this.debounceTimeout);
            this.debounceTimeout = null;
        }
    }
}
