import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    stats = null;
    errorMessage = null;
    intervalId = null;
    inFlight = false;

    handleVisibilityChange = () => {
        if (document.visibilityState === 'hidden') {
            this.stopPolling();
        } else {
            this.startPolling();
        }
    };

    connectedCallback() {
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
        if (document.visibilityState !== 'hidden') {
            this.startPolling();
        }
    }

    disconnectedCallback() {
        this.stopPolling();
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    }

    startPolling() {
        this.stopPolling();
        this.loadStats();
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        this.intervalId = setInterval(() => {
            this.loadStats();
        }, REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this.intervalId !== null) {
            clearInterval(this.intervalId);
            this.intervalId = null;
        }
    }

    async loadStats() {
        if (this.inFlight || document.visibilityState === 'hidden') {
            return;
        }

        this.inFlight = true;
        try {
            const result = await getQueueStats();
            this.stats = result;
            this.errorMessage = null;
        } catch (error) {
            this.errorMessage = error?.body?.message || error?.message;
        } finally {
            this.inFlight = false;
        }
    }
}
