import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value;
    activeIndex = -1;

    @api
    get options() {
        return this._options;
    }

    set options(val) {
        this._options = Array.isArray(val) ? val : [];
        this.syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }

    set value(val) {
        this._value = val;
        this.syncActiveIndex();
    }

    get computedOptions() {
        return this._options.map((opt, index) => ({
            value: opt.value,
            label: opt.label,
            id: `option-${index}`,
            ariaSelected: opt.value === this._value ? 'true' : 'false'
        }));
    }

    get activeDescendantId() {
        if (this.activeIndex >= 0 && this.activeIndex < this._options.length) {
            return `option-${this.activeIndex}`;
        }
        return undefined;
    }

    syncActiveIndex() {
        if (!this._options || this._options.length === 0) {
            this.activeIndex = -1;
            return;
        }
        const selectedIndex = this._options.findIndex((opt) => opt.value === this._value);
        this.activeIndex = selectedIndex !== -1 ? selectedIndex : 0;
    }

    handleKeyDown(event) {
        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                if (this._options.length > 0 && this.activeIndex < this._options.length - 1) {
                    this.activeIndex += 1;
                }
                break;
            case 'ArrowUp':
                event.preventDefault();
                if (this._options.length > 0 && this.activeIndex > 0) {
                    this.activeIndex -= 1;
                }
                break;
            case 'Home':
                event.preventDefault();
                if (this._options.length > 0) {
                    this.activeIndex = 0;
                }
                break;
            case 'End':
                event.preventDefault();
                if (this._options.length > 0) {
                    this.activeIndex = this._options.length - 1;
                }
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this.selectOptionAtIndex(this.activeIndex);
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const clickedValue = event.currentTarget.dataset.value;
        const index = this._options.findIndex(
            (opt) => opt.value === clickedValue || String(opt.value) === clickedValue
        );
        if (index !== -1) {
            this.selectOptionAtIndex(index);
        }
    }

    selectOptionAtIndex(index) {
        if (index < 0 || index >= this._options.length) {
            return;
        }
        this.activeIndex = index;
        const nextValue = this._options[index].value;
        if (nextValue !== this._value) {
            this._value = nextValue;
            this.dispatchEvent(
                new CustomEvent('change', {
                    detail: { value: nextValue }
                })
            );
        }
    }
}
