import { LightningElement, api, track } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;
    @track items = [];
    newLabel = '';
    nextId = 1;
    _tasks = [];

    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        this._tasks = value;
        this.items = Array.isArray(value) ? value.map((task) => ({ ...task })) : [];
    }

    get displayHeading() {
        return this.heading ? String(this.heading).toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel =
            event.detail && event.detail.value !== undefined
                ? event.detail.value
                : event.target.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }
        let id = `new-${this.nextId++}`;
        while (this.items.some((task) => String(task.id) === id)) {
            id = `new-${this.nextId++}`;
        }
        this.items = [...this.items, { id, label, done: false }];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const targetId = event.target.dataset.id;
        this.items = this.items.map((task) =>
            String(task.id) === targetId ? { ...task, done: !task.done } : task
        );
    }
}
