public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        List<npsp__DataImport__c> stagedImports = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            stagedImports.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c = gift != null ? gift.firstName : null,
                npsp__Contact1_Lastname__c = gift != null ? gift.lastName : null,
                npsp__Contact1_Personal_Email__c = gift != null ? gift.email : null,
                npsp__Donation_Amount__c = gift != null ? gift.amount : null,
                npsp__Donation_Date__c = gift != null ? gift.giftDate : null,
                npsp__Donation_Donor__c = 'Contact1'
            ));
        }

        insert stagedImports;

        npsp__Data_Import_Settings__c settings = getDataImportSettings();
        npsp.BDI_DataImport_API.processDataImportRecords(settings, stagedImports);

        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>([
            SELECT
                Id,
                npsp__Status__c,
                npsp__Contact1Imported__c,
                npsp__DonationImported__c,
                npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :stagedImports
        ]);

        for (npsp__DataImport__c staged : stagedImports) {
            npsp__DataImport__c processed = processedById.get(staged.Id);
            ImportResult result = new ImportResult();
            result.success = (processed.npsp__Status__c == npsp.BDI_DataImport_API.STATUS_IMPORTED);
            result.contactId = processed.npsp__Contact1Imported__c;
            result.opportunityId = processed.npsp__DonationImported__c;
            result.errorMessage = result.success ? null : processed.npsp__FailureInformation__c;
            results.add(result);
        }

        return results;
    }

    private static npsp__Data_Import_Settings__c getDataImportSettings() {
        npsp__Data_Import_Settings__c settings = npsp__Data_Import_Settings__c.getOrgDefaults();
        if (settings == null) {
            settings = new npsp__Data_Import_Settings__c();
        }
        if (String.isBlank(settings.npsp__Contact_Matching_Rule__c)) {
            settings.npsp__Contact_Matching_Rule__c = npsp.BDI_DataImport_API.CONTACT_FIRST_LAST_AND_EMAIL;
        }
        if (String.isBlank(settings.npsp__Donation_Matching_Behavior__c)) {
            settings.npsp__Donation_Matching_Behavior__c = npsp.BDI_DataImport_API.Do_Not_Match;
        }
        if (String.isBlank(settings.npsp__Donation_Matching_Rule__c)) {
            settings.npsp__Donation_Matching_Rule__c = 'npsp__Donation_Amount__c;npsp__Donation_Date__c';
        }
        if (settings.npsp__Donation_Date_Range__c == null) {
            settings.npsp__Donation_Date_Range__c = 0;
        }
        if (settings.npsp__Batch_Size__c == null) {
            settings.npsp__Batch_Size__c = 50;
        }
        return settings;
    }
}
