public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;

        public SoftCreditRequest() {}

        public SoftCreditRequest(Id opportunityId, Id contactId, Decimal amount, String role) {
            this.opportunityId = opportunityId;
            this.contactId = contactId;
            this.amount = amount;
            this.role = role;
        }
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();

        for (SoftCreditRequest req : requests) {
            if (req == null || req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Each request must specify an opportunityId and contactId.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be positive.');
            }
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException('Cannot assign a partial soft credit to the primary contact.');
            }
            if (opp.Amount == null || req.amount > opp.Amount) {
                throw new SoftCreditException('Partial soft credit amount cannot exceed the opportunity amount.');
            }
        }

        Map<String, List<OpportunityContactRole>> existingOcrsByKey = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds
              AND ContactId IN :contactIds
        ]) {
            String key = getKey(ocr.OpportunityId, ocr.ContactId);
            if (!existingOcrsByKey.containsKey(key)) {
                existingOcrsByKey.put(key, new List<OpportunityContactRole>());
            }
            existingOcrsByKey.get(key).add(ocr);
        }

        Map<String, npsp__Partial_Soft_Credit__c> existingPscByKey = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                   npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds
              AND npsp__Contact__c IN :contactIds
        ]) {
            String key = getKey(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            if (!existingPscByKey.containsKey(key)) {
                existingPscByKey.put(key, psc);
            }
        }

        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> targetOcrByKey = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = getKey(req.opportunityId, req.contactId);
            List<OpportunityContactRole> ocrList = existingOcrsByKey.get(key);

            if (ocrList == null || ocrList.isEmpty()) {
                OpportunityContactRole newOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrsToInsert.add(newOcr);
                targetOcrByKey.put(key, newOcr);
            } else {
                OpportunityContactRole targetOcr = selectTargetOcr(ocrList, existingPscByKey.get(key));
                for (OpportunityContactRole ocr : ocrList) {
                    if (ocr.Id != targetOcr.Id) {
                        ocrsToDelete.add(ocr);
                    }
                }
                if (targetOcr.Role == null || !targetOcr.Role.equals(req.role)) {
                    targetOcr.Role = req.role;
                    ocrsToUpdate.add(targetOcr);
                }
                targetOcrByKey.put(key, targetOcr);
            }
        }

        if (!ocrsToDelete.isEmpty()) {
            delete ocrsToDelete;
        }
        if (!ocrsToInsert.isEmpty()) {
            insert ocrsToInsert;
        }
        if (!ocrsToUpdate.isEmpty()) {
            update ocrsToUpdate;
        }

        List<npsp__Partial_Soft_Credit__c> pscsToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToUpdate = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = getKey(req.opportunityId, req.contactId);
            OpportunityContactRole targetOcr = targetOcrByKey.get(key);
            npsp__Partial_Soft_Credit__c existingPsc = existingPscByKey.get(key);

            if (existingPsc != null) {
                existingPsc.npsp__Amount__c = req.amount;
                existingPsc.npsp__Role_Name__c = req.role;
                existingPsc.npsp__Contact_Role_ID__c = String.valueOf(targetOcr.Id);
                pscsToUpdate.add(existingPsc);
            } else {
                npsp__Partial_Soft_Credit__c newPsc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = String.valueOf(targetOcr.Id)
                );
                pscsToInsert.add(newPsc);
            }
        }

        if (!ocrsToDelete.isEmpty() && !pscsToInsert.isEmpty() && !pscsToUpdate.isEmpty()) {
            List<npsp__Partial_Soft_Credit__c> pscsToUpsert = new List<npsp__Partial_Soft_Credit__c>();
            pscsToUpsert.addAll(pscsToInsert);
            pscsToUpsert.addAll(pscsToUpdate);
            upsert pscsToUpsert;
        } else {
            if (!pscsToInsert.isEmpty()) {
                insert pscsToInsert;
            }
            if (!pscsToUpdate.isEmpty()) {
                update pscsToUpdate;
            }
        }
    }

    private static OpportunityContactRole selectTargetOcr(
        List<OpportunityContactRole> ocrList,
        npsp__Partial_Soft_Credit__c existingPsc
    ) {
        if (existingPsc != null && String.isNotBlank(existingPsc.npsp__Contact_Role_ID__c)) {
            Id linkedOcrId;
            try {
                linkedOcrId = (Id) existingPsc.npsp__Contact_Role_ID__c;
            } catch (Exception e) {
                linkedOcrId = null;
            }
            if (linkedOcrId != null) {
                for (OpportunityContactRole ocr : ocrList) {
                    if (ocr.Id == linkedOcrId) {
                        return ocr;
                    }
                }
            }
        }
        return ocrList[0];
    }

    private static String getKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + ':' + String.valueOf(contactId);
    }
}
