public with sharing class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null || amount == null || amount <= 0 || giftDate == null) {
            throw new IllegalArgumentException('Contact, a positive amount, and gift date are required.');
        }

        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }

        Contact primaryContact = contacts[0];

        String contactFullName = String.isBlank(primaryContact.FirstName)
            ? primaryContact.LastName
            : primaryContact.FirstName + ' ' + primaryContact.LastName;
        String formattedDate = Datetime.newInstanceGmt(
            giftDate.year(),
            giftDate.month(),
            giftDate.day(),
            12, 0, 0
        ).formatGmt('yyyy-MM-dd');
        String oppName = contactFullName + ' Donation ' + formattedDate;

        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = primaryContact.AccountId,
            npsp__Primary_Contact__c = primaryContact.Id,
            Amount = amount,
            CloseDate = giftDate,
            StageName = 'Closed Won'
        );
        insert opp;

        reconcileContactRoles(opp.Id, primaryContact);
        reconcilePayments(opp.Id, amount, giftDate);

        return opp.Id;
    }

    private static void reconcileContactRoles(Id opportunityId, Contact primaryContact) {
        List<Contact> otherMembers = new List<Contact>();
        if (primaryContact.AccountId != null) {
            otherMembers = [
                SELECT Id
                FROM Contact
                WHERE AccountId = :primaryContact.AccountId
                AND Id != :primaryContact.Id
            ];
        }

        Set<Id> householdContactIds = new Set<Id>{ primaryContact.Id };
        for (Contact member : otherMembers) {
            householdContactIds.add(member.Id);
        }

        List<OpportunityContactRole> existingRoles = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
            ORDER BY IsPrimary DESC, CreatedDate ASC
        ];

        Map<Id, OpportunityContactRole> roleByContactId = new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete = new List<OpportunityContactRole>();

        for (OpportunityContactRole ocr : existingRoles) {
            if (ocr.ContactId == null || !householdContactIds.contains(ocr.ContactId) || roleByContactId.containsKey(ocr.ContactId)) {
                rolesToDelete.add(ocr);
            } else {
                roleByContactId.put(ocr.ContactId, ocr);
            }
        }

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();

        if (roleByContactId.containsKey(primaryContact.Id)) {
            OpportunityContactRole donorRole = roleByContactId.get(primaryContact.Id);
            if (donorRole.Role != 'Donor' || donorRole.IsPrimary != true) {
                donorRole.Role = 'Donor';
                donorRole.IsPrimary = true;
                rolesToUpdate.add(donorRole);
            }
        } else {
            rolesToInsert.add(new OpportunityContactRole(
                OpportunityId = opportunityId,
                ContactId = primaryContact.Id,
                Role = 'Donor',
                IsPrimary = true
            ));
        }

        for (Contact member : otherMembers) {
            if (roleByContactId.containsKey(member.Id)) {
                OpportunityContactRole memberRole = roleByContactId.get(member.Id);
                if (memberRole.Role != 'Household Member' || memberRole.IsPrimary != false) {
                    memberRole.Role = 'Household Member';
                    memberRole.IsPrimary = false;
                    rolesToUpdate.add(memberRole);
                }
            } else {
                rolesToInsert.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = member.Id,
                    Role = 'Household Member',
                    IsPrimary = false
                ));
            }
        }

        if (!rolesToDelete.isEmpty()) {
            delete rolesToDelete;
        }
        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }
        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }
    }

    private static void reconcilePayments(Id opportunityId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c, npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            ORDER BY npe01__Paid__c DESC, CreatedDate ASC
        ];

        if (existingPayments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
        } else {
            npe01__OppPayment__c primaryPayment = existingPayments[0];
            if (primaryPayment.npe01__Payment_Amount__c != amount ||
                primaryPayment.npe01__Payment_Date__c != giftDate ||
                primaryPayment.npe01__Scheduled_Date__c != giftDate ||
                primaryPayment.npe01__Paid__c != true) {
                primaryPayment.npe01__Payment_Amount__c = amount;
                primaryPayment.npe01__Payment_Date__c = giftDate;
                primaryPayment.npe01__Scheduled_Date__c = giftDate;
                primaryPayment.npe01__Paid__c = true;
                update primaryPayment;
            }

            if (existingPayments.size() > 1) {
                List<npe01__OppPayment__c> duplicatePayments = new List<npe01__OppPayment__c>();
                for (Integer i = 1; i < existingPayments.size(); i++) {
                    duplicatePayments.add(existingPayments[i]);
                }
                delete duplicatePayments;
            }
        }
    }
}
