```apex
global with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final String TASK_SUBJECT = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS = 'Not Started';

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        if (
            triggerAction != npsp.TDTM_Runnable.Action.AfterInsert &&
            triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate
        ) {
            return dmlWrapper;
        }

        Map<Id, Opportunity> oldOppMap = new Map<Id, Opportunity>();
        if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate && oldlist != null) {
            for (SObject sObj : oldlist) {
                Opportunity oldOpp = (Opportunity) sObj;
                if (oldOpp.Id != null) {
                    oldOppMap.put(oldOpp.Id, oldOpp);
                }
            }
        }

        List<Opportunity> qualifyingOpps = new List<Opportunity>();
        Set<Id> qualifyingOppIds = new Set<Id>();

        for (Integer i = 0; i < newlist.size(); i++) {
            Opportunity newOpp = (Opportunity) newlist[i];
            if (!isQualifyingMajorGift(newOpp)) {
                continue;
            }

            if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
                Opportunity oldOpp = newOpp.Id != null ? oldOppMap.get(newOpp.Id) : null;
                if (oldOpp == null && oldlist != null && i < oldlist.size()) {
                    oldOpp = (Opportunity) oldlist[i];
                }
                if (isQualifyingMajorGift(oldOpp)) {
                    continue;
                }
            }

            qualifyingOpps.add(newOpp);
            if (newOpp.Id != null) {
                qualifyingOppIds.add(newOpp.Id);
            }
        }

        if (qualifyingOpps.isEmpty()) {
            return dmlWrapper;
        }

        Set<Id> existingTaskOppIds = new Set<Id>();
        if (!qualifyingOppIds.isEmpty()) {
            for (Task existingTask : [
                SELECT WhatId
                FROM Task
                WHERE WhatId IN :qualifyingOppIds
                  AND Subject = :TASK_SUBJECT
            ]) {
                existingTaskOppIds.add(existingTask.WhatId);
            }
        }

        List<Task> tasksToInsert = new List<Task>();
        for (Opportunity opp : qualifyingOpps) {
            if (opp.Id != null && existingTaskOppIds.contains(opp.Id)) {
                continue;
            }
            tasksToInsert.add(
                new Task(
                    Subject = TASK_SUBJECT,
                    Priority = TASK_PRIORITY,
                    Status = TASK_STATUS,
                    WhatId = opp.Id,
                    WhoId = opp.npsp__Primary_Contact__c,
                    OwnerId = opp.OwnerId,
                    ActivityDate = opp.CloseDate != null ? opp.CloseDate.addDays(3) : null
                )
            );
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return dmlWrapper;
    }

    private static Boolean isQualifyingMajorGift(Opportunity opp) {
        if (opp == null) {
            return false;
        }
        Boolean isClosedWon = (opp.IsWon == true) || (opp.StageName == 'Closed Won');
        return isClosedWon && opp.Amount != null && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }
}
