        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        Assert.isTrue(
            triggerNew[0].hasErrors(),
            'Expected an error when Amount is reduced from 1000 to 499.'
        );
        Assert.areEqual(
            1,
            triggerNew[0].getErrors().size(),
            'Expected exactly one error on the Opportunity.'
        );
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            triggerNew[0].getErrors()[0].getMessage(),
            'Expected the error message to match ERROR_MESSAGE.'
        );
    }

    @IsTest
    private static void reductionOfExactlyHalfShouldBeAccepted() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
