        List<Opportunity> triggerOld = new List<Opportunity>{
            new Opportunity(Id = tooLowFirstId, Amount = 1000),
            new Opportunity(Id = exactHalfId, Amount = 1000),
            new Opportunity(Id = increasedId, Amount = 1000),
            new Opportunity(Id = nullPreviousId, Amount = null),
