        List<Opportunity> triggerNew = new List<Opportunity>{
            tooLowFirstNew,
            exactHalfNew,
            increasedNew,
            nullPreviousNew,
            tooLowSecondNew
        };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        Assert.isTrue(tooLowFirstNew.hasErrors(), 'First violating record should have an error.');
        Assert.areEqual(1, tooLowFirstNew.getErrors().size(), 'First violating record should have one error.');
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            tooLowFirstNew.getErrors()[0].getMessage(),
