        );

        Assert.isTrue(tooLowSecondNew.hasErrors(), 'Second violating record should have an error.');
        Assert.areEqual(1, tooLowSecondNew.getErrors().size(), 'Second violating record should have one error.');
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
