        Assert.isFalse(increasedNew.hasErrors(), 'Increased Amount record should not have errors.');
        Assert.areEqual(0, increasedNew.getErrors().size(), 'Increased Amount record should have 0 errors.');

        Assert.isFalse(nullPreviousNew.hasErrors(), 'Null previous Amount record should not have errors.');
        Assert.areEqual(0, nullPreviousNew.getErrors().size(), 'Null previous Amount record should have 0 errors.');
    }
