```apex
public inherited sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    @TestVisible
    private static final String DUPLICATE_EMAIL_ERROR = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        preventDuplicateEmail(triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        preventDuplicateEmail(triggerNew, triggerOld);
    }

    private void preventDuplicateEmail(List<SObject> triggerNew, List<SObject> triggerOld) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        Map<Id, Contact> oldMap = new Map<Id, Contact>();
        if (triggerOld != null) {
            for (SObject oldSObj : triggerOld) {
                Contact oldContact = (Contact) oldSObj;
                if (oldContact != null && oldContact.Id != null) {
                    oldMap.put(oldContact.Id, oldContact);
                }
            }
        }

        List<Contact> contactsToCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        Map<String, Set<Id>> existingIdsByKey = new Map<String, Set<Id>>();
        Set<String> seenInBatch = new Set<String>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Contact newContact = (Contact) triggerNew[i];
            if (newContact == null || newContact.AccountId == null || String.isBlank(newContact.Email)) {
                continue;
            }

            if (triggerOld != null) {
                Contact oldContact = null;
                if (newContact.Id != null && oldMap.containsKey(newContact.Id)) {
                    oldContact = oldMap.get(newContact.Id);
                } else if (i < triggerOld.size()) {
                    oldContact = (Contact) triggerOld[i];
                }

                if (oldContact != null) {
                    Boolean accountChanged = newContact.AccountId != oldContact.AccountId;
                    Boolean emailChanged = oldContact.Email == null || !newContact.Email.equals(oldContact.Email);
                    if (!accountChanged && !emailChanged) {
                        String unchangedKey = buildKey(newContact.AccountId, newContact.Email);
                        if (newContact.Id != null) {
                            addExistingId(existingIdsByKey, unchangedKey, newContact.Id);
                        } else {
                            seenInBatch.add(unchangedKey);
                        }
                        continue;
                    }
                }
            }

            String normalizedEmail = newContact.Email.trim().toLowerCase();
            contactsToCheck.add(newContact);
            accountIds.add(newContact.AccountId);
            emails.add(normalizedEmail);
        }

        if (contactsToCheck.isEmpty()) {
            return;
        }

        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email IN :emails
        ]) {
            if (existing.AccountId != null && String.isNotBlank(existing.Email)) {
                addExistingId(existingIdsByKey, buildKey(existing.AccountId, existing.Email), existing.Id);
            }
        }

        for (Contact contactToCheck : contactsToCheck) {
            String key = buildKey(contactToCheck.AccountId, contactToCheck.Email);
            Boolean hasDbConflict = false;
            Set<Id> existingIds = existingIdsByKey.get(key);
            if (existingIds != null && !existingIds.isEmpty()) {
                if (contactToCheck.Id == null || existingIds.size() > 1 || !existingIds.contains(contactToCheck.Id)) {
                    hasDbConflict = true;
                }
            }

            if (hasDbConflict || seenInBatch.contains(key)) {
                contactToCheck.addError(DUPLICATE_EMAIL_ERROR);
            } else {
                seenInBatch.add(key);
            }
        }
    }

    private static String buildKey(Id accountId, String email) {
        return String.valueOf(accountId) + ':' + email.trim().toLowerCase();
    }

    private static void addExistingId(Map<String, Set<Id>> existingIdsByKey, String key, Id contactId) {
        Set<Id> ids = existingIdsByKey.get(key);
        if (ids == null) {
            ids = new Set<Id>();
            existingIdsByKey.put(key, ids);
        }
        ids.add(contactId);
    }
}
